bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try {
 const q=await db.query("SELECT l.sample_duration_seconds,l.sample_file_id=l.paid_video_file_id AS sample_is_main,l.sample_file_id=l.thumbnail_file_id AS sample_is_thumbnail FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)process.exit(61);
 const r=q.rows[0],secs=Number(r.sample_duration_seconds);
 if(r.sample_is_main===true)process.exit(32);
 if(r.sample_is_thumbnail===true)process.exit(33);
 if(!Number.isFinite(secs)||secs<=0)process.exit(34);
 if(secs>30)process.exit(31);
 console.log('OLD_VIDEO_SAMPLE_RECORD_DURATION_WITHIN_30_SECONDS=PASS');
}catch{process.exitCode=70}finally{await db.end()}
JS
